package com.sobrenaturaldirector.mutation.model;
import java.util.*;import com.sobrenaturaldirector.domain.StableId;import com.sobrenaturaldirector.mutation.safety.MutationSafetyAssessment;
public final class MutationTransactionPlan {private final String id;private final List<MutationIntent> intents;private final List<String> order;private final MutationBudget budget;private final MutationSafetyAssessment safety;private final int verificationCount;public MutationTransactionPlan(String id,Collection<MutationIntent> intents,List<String> order,MutationBudget budget,MutationSafetyAssessment safety,int verificationCount){this.id=StableId.require(id,"transactionId");this.intents=Collections.unmodifiableList(new ArrayList<MutationIntent>(intents==null?Collections.<MutationIntent>emptyList():intents));this.order=Collections.unmodifiableList(new ArrayList<String>(order==null?Collections.<String>emptyList():order));this.budget=budget;this.safety=safety;this.verificationCount=verificationCount;}public String getId(){return id;}public List<MutationIntent> getIntents(){return intents;}public List<String> getDeterministicOrder(){return order;}public MutationBudget getBudget(){return budget;}public MutationSafetyAssessment getSafety(){return safety;}public int getVerificationCount(){return verificationCount;}}
